import{_ as a,o as d,c as r,a as e}from"./chunks/framework.Ld7uezS_.js";const p=JSON.parse('{"title":"1. 设施监控","description":"","frontmatter":{},"headers":[],"relativePath":"skill/01-monitoring.md","filePath":"skill/01-monitoring.md","lastUpdated":1787288798000}'),l={name:"skill/01-monitoring.md"};function i(o,t,h,n,s,b){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_1-设施监控" tabindex="-1">1. 设施监控 <a class="header-anchor" href="#_1-设施监控" aria-label="Permalink to &quot;1. 设施监控&quot;">​</a></h1><h2 id="本章定位" tabindex="-1">本章定位 <a class="header-anchor" href="#本章定位" aria-label="Permalink to &quot;本章定位&quot;">​</a></h2><p>本职业功能主要对应<strong>消防设施监控操作方向</strong>。监控不是盯着屏幕等报警，而是持续判断系统是否处于正常、可用和受控状态，并对火警、故障、监管和屏蔽信息做出不同处理。</p><h2 id="一、先认识-控制器-是什么" tabindex="-1">一、先认识“控制器”是什么 <a class="header-anchor" href="#一、先认识-控制器-是什么" aria-label="Permalink to &quot;一、先认识“控制器”是什么&quot;">​</a></h2><p>控制器不是普通电脑屏幕，而是消防设施接收信息、显示状态、发出控制指令并保存记录的核心设备。零基础可以先把它理解成“消防系统的收发室”：现场设备把信息送进来，控制器把信息分类显示；需要联动时，控制器再把指令送给泵、风机、广播、卷帘等执行设备，并等待运行、到位或故障反馈。</p><h3 id="_1-先认识四类设备角色" tabindex="-1">1. 先认识四类设备角色 <a class="header-anchor" href="#_1-先认识四类设备角色" aria-label="Permalink to &quot;1. 先认识四类设备角色&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>常见设备</th><th>它在信号链中做什么</th></tr></thead><tbody><tr><td>输入设备</td><td>感烟/感温探测器、手动报警按钮、水流指示器、压力开关</td><td>把现场烟、温、人工触发或水力状态变成系统可识别的信息</td></tr><tr><td>控制显示设备</td><td>火灾报警控制器、联动控制器、图形显示装置</td><td>接收、分类、显示信息，按条件输出控制指令并保存记录</td></tr><tr><td>执行设备</td><td>消防泵、风机、风阀、广播、卷帘、照明等</td><td>接到指令后完成启动、关闭、切换或播报等动作</td></tr><tr><td>反馈设备/信号</td><td>运行触点、到位开关、故障触点、输入模块</td><td>把执行设备的实际状态返回控制器</td></tr></tbody></table><p>因此，“控制器显示有输出”只说明指令链的一部分完成；还要分别确认现场是否动作、是否到位、是否有反馈。</p><h3 id="_2-先认识控制器上的四类信息" tabindex="-1">2. 先认识控制器上的四类信息 <a class="header-anchor" href="#_2-先认识控制器上的四类信息" aria-label="Permalink to &quot;2. 先认识控制器上的四类信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>信息</th><th>表示什么</th><th>第一反应</th></tr></thead><tbody><tr><td>火灾报警</td><td>探测器、手动按钮等报告疑似火情</td><td>记录位置，按预案核实、报告、组织处置</td></tr><tr><td>故障</td><td>设备、线路、电源或通信可能异常</td><td>查询故障对象和影响，报告维修，不当作火警也不当作正常</td></tr><tr><td>监管报警</td><td>受监管设备或输入状态异常</td><td>查明输入对象和现场状态，按单位程序报告</td></tr><tr><td>屏蔽/隔离</td><td>某设备或功能暂时不参与监视/联动</td><td>确认授权、原因、范围、临时防护和恢复要求</td></tr></tbody></table><p>还要识别正常监视、主电/备电、手动/自动、联动启动和反馈状态。</p><h3 id="_3-正常监视-到底是什么" tabindex="-1">3. “正常监视”到底是什么 <a class="header-anchor" href="#_3-正常监视-到底是什么" aria-label="Permalink to &quot;3. “正常监视”到底是什么&quot;">​</a></h3><p>“正常监视”不是屏幕亮着就算正常，而是系统正在按设计持续接收现场信息，且没有未处理的火警、故障、监管、屏蔽/隔离或异常手动状态。初学者可按下面顺序观察：</p><ol><li>控制器是否显示正常监视或等效状态；</li><li>是否存在未处理的火警、故障、监管、屏蔽/隔离信息；</li><li>主电和备用电源状态是否符合要求；</li><li>相关泵、风机、阀门、卷帘等是否处于规定的自动/联动状态；</li><li>是否有设备停用、手动、维修或临时防护记录未收口。</li></ol><p>不同品牌控制器按钮名称可能不同，训练时要把页面上的通用逻辑对应到具体设备说明书。</p><h3 id="_4-初学者如何读懂控制器界面" tabindex="-1">4. 初学者如何读懂控制器界面 <a class="header-anchor" href="#_4-初学者如何读懂控制器界面" aria-label="Permalink to &quot;4. 初学者如何读懂控制器界面&quot;">​</a></h3><p>看到控制器界面时，不要只盯着颜色或声音。先按“状态—对象—时间—影响—下一步”五个问题读取：</p><table tabindex="0"><thead><tr><th>要读什么</th><th>零基础理解</th><th>不能直接推出什么</th></tr></thead><tbody><tr><td>状态类别</td><td>当前是火警、故障、监管、屏蔽/隔离、启动还是正常监视</td><td>不能因为有一条信息就断定整套系统都异常</td></tr><tr><td>对象位置</td><td>设备类型、回路、地址、区域或分区，说明是哪一个对象发出信息</td><td>不能把控制室标签直接当成现场实际位置，需结合图纸/标签核对</td></tr><tr><td>时间和顺序</td><td>信息何时出现、先出现什么、后出现什么，帮助判断因果关系</td><td>不能用后来出现的显示覆盖最初现象</td></tr><tr><td>影响范围</td><td>单点、同回路、同分区还是多系统同时出现</td><td>不能只看一条故障就更换单个设备</td></tr><tr><td>下一步</td><td>核实、报告、按方案测试、维修升级或恢复记录</td><td>不能未经授权直接复位、屏蔽、断电或改配置</td></tr></tbody></table><h3 id="_5-消音、复位、确认和屏蔽不是一回事" tabindex="-1">5. 消音、复位、确认和屏蔽不是一回事 <a class="header-anchor" href="#_5-消音、复位、确认和屏蔽不是一回事" aria-label="Permalink to &quot;5. 消音、复位、确认和屏蔽不是一回事&quot;">​</a></h3><ul><li><strong>消音</strong>：只处理提示声响，让人员能够继续读取信息；原事件可能仍然存在。</li><li><strong>确认</strong>：表示人员已经读取并接手处理信息，通常要留下时间、对象和责任人记录；确认不等于故障排除。</li><li><strong>复位</strong>：在触发条件已经消失、现场允许恢复时，让控制器和相关设备回到规定监视状态；复位后仍应检查是否重新报警或产生故障。</li><li><strong>屏蔽/隔离</strong>：让特定设备或功能暂时不参与监视或联动，保护范围会减少，必须有授权、原因、范围、临时措施、责任人和恢复期限。</li></ul><p>因此，看到一条信息时的正确顺序是：<strong>先读清并记录 → 判断保护影响 → 按预案核实 → 由授权人员决定消音/复位/屏蔽 → 验证结果 → 记录恢复或遗留风险</strong>。不能把“控制器安静了”作为“系统正常”的结论。</p><h2 id="二、报警信息处理闭环" tabindex="-1">二、报警信息处理闭环 <a class="header-anchor" href="#二、报警信息处理闭环" aria-label="Permalink to &quot;二、报警信息处理闭环&quot;">​</a></h2><ol><li><strong>看清楚</strong>：查看液晶屏、指示灯、地址、设备类型、时间和区域；</li><li><strong>记下来</strong>：记录报警类别、地址、时间、数量和当前控制方式；</li><li><strong>分类型</strong>：判断是火警、故障、监管、屏蔽还是反馈信息；</li><li><strong>核实现场</strong>：通过消防电话、对讲、现场巡查或授权人员确认；</li><li><strong>按预案处理</strong>：火警优先保护人员、报警、疏散和报告；故障转入维修和临时防护流程；</li><li><strong>确认结果</strong>：查看现场动作、控制器反馈和新增信息；</li><li><strong>恢复记录</strong>：满足复位条件后复位并确认正常监视，不能恢复时保留信息、升级报告。</li></ol><h2 id="三、为什么不能先消音再说" tabindex="-1">三、为什么不能先消音再说 <a class="header-anchor" href="#三、为什么不能先消音再说" aria-label="Permalink to &quot;三、为什么不能先消音再说&quot;">​</a></h2><p>消音只是停止或暂时停止声响提示，不等于火警或故障已经排除。可以在确认信息已经被记录、有人负责核实后按规程消音，但不能为了安静而直接复位、屏蔽或断电。</p><h2 id="四、训练任务" tabindex="-1">四、训练任务 <a class="header-anchor" href="#四、训练任务" aria-label="Permalink to &quot;四、训练任务&quot;">​</a></h2><p>在模拟控制器上分别练习：</p><ul><li>看到火灾报警时说出地址、时间、核实方式和报告对象；</li><li>看到故障时指出是电源、回路、设备还是通信类信息，并说明不能做什么；</li><li>看到屏蔽时说出授权、原因、影响范围、临时措施和恢复责任人；</li><li>处置结束后逐项检查自动/手动、主/备电、联动和正常监视状态。</li></ul><blockquote><p>实际设备操作必须在鉴定站或有资质人员指导下进行，不可自行制造短路、断线或屏蔽故障。</p></blockquote><h2 id="五、考核记录模板" tabindex="-1">五、考核记录模板 <a class="header-anchor" href="#五、考核记录模板" aria-label="Permalink to &quot;五、考核记录模板&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>信息类别</th><th>地址/设备</th><th>核实结果</th><th>处置动作</th><th>系统恢复状态</th><th>报告对象</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="六、自测" tabindex="-1">六、自测 <a class="header-anchor" href="#六、自测" aria-label="Permalink to &quot;六、自测&quot;">​</a></h2><ol><li>消音和复位有什么区别？</li><li>火灾报警和故障报警的处置重点有什么不同？</li><li>为什么屏蔽必须有授权、原因和恢复要求？</li><li>操作结束至少要确认哪些状态？</li></ol><blockquote><p>参考：<a href="https://xfhyjd.119.gov.cn/zwossread/open1File/FirefightingSkillsAssessmentSystem/2025-11-13/4f0f6d863cf843228b5ce52030b59bb7/16193156145476990d82b-cb9d-43a7-a5f0-522abe3d1f8c%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E8%81%8C%E4%B8%9A%E6%8A%80%E8%83%BD%E6%A0%87%E5%87%86%E2%80%94%E2%80%94%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98.pdf" target="_blank" rel="noreferrer">《消防设施操作员国家职业技能标准（2019年版）》</a>；具体控制器按钮和评分点以设备说明书、鉴定站评分表为准。</p></blockquote>',34)])])}const u=a(l,[["render",i]]);export{p as __pageData,u as default};
